    :raise TypeError: if protocol version is not passed in a tuple
    """
    protocol_handlers_dict = {}
    if protocol_version is None:
        for protocol_version in cls.RESPONSE_HANDLERS:
            protocol_handlers_dict[protocol_version] = cls.RESPONSE_HANDLERS[protocol_version]
    elif isinstance(protocol_version, tuple):
