def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
    if db is None and imp_user is None:
        raise ValueError("Must provide either db or imp_user to start a transaction.")
    queue_name = porto_apis.DEFAULT_QUEUE_NAME
    if mode == "READ":
        queue_name = porto_apis.READ_QUEUE_NAME
    elif mode == "WRITE":
        queue_name = porto_apis.WRITE_QUEUE_NAME
    else:
        raise ValueError("Invalid mode. Must be 'READ' or 'WRITE'.")

    message = porto_apis.BeginMessage(mode, bookmarks, metadata)
    message.set_timeout(timeout)

    for hook in dehydration_hooks.values():
        message.dehydration_hooks[hook.type] = hook

    for hook in hydration_hooks.values():
        message.hydration_hooks[hook.type] = hook

    if db is not None:
        message.db = db
    if imp_user is not None:
        message.imp_user = imp_user

    conformity.assert_mutation(message)

    reply = yield self.ctrl.write_message(queue_name, message)
    return Response(reply)

import math

def round_half_to_even(n):
    """
    Round a number to the nearest even integer if it is halfway between two integers.

    :param n: The number to round
    :return: The rounded number
    """
    # If n is halfway between two integers, round to the nearest even one.
    if n % 2 == 0.5:
        return math.ceil(n - 0.5)
    else:
        return round(n)

def round_half_to_even(n):
    """
    Rounds the input value to the nearest even integer.

    :param n:
    :return:
    """
    half = 0.5
    if n < 0:
        n = -n
    smaller = n - half

    if smaller - n <= 1 / 2:
        ceilange = n
    else:
        ceilange = n + half

    return math.floor(ceilange)

