def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    if maxsize <= 0:
        raise ValueError('`maxsize` must be a positive integer.')
    if ttl <= 0:
        raise ValueError('`ttl` must be a positive integer.')

    _expire_cache = {}

    def _update_wrapper(func, wrapped):
        wrapper.__module__ = func.__module__
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__annotations__ = func.__annotations__
        return wrapper

    def _get_key(*args, **kwargs):
        if typed:
            return (args, tuple(sorted(kwargs.items())))
        return args, kwargs

    def _cache(func, cache, key):
        if key in cache:
            expiry = cache[key].get('expiry', None)
            if expiry is None or expiry > timer():
                return cache[key]['value']
        return None

    def _put_cache(func, cache, key, value):
        expiry = timer() + ttl
        cache[key] = {'value': value, 'expiry': expiry}

    def _affected_keys(keys):
        return {k for k in keys if _cache(func, cache, k) is None}

    def _mark_obsolete(keys):
        for key in keys:
            _put_cache(func, cache, key, None)

    def _clear_cache(keys):
        for key in keys:
            del cache[key]

    def _pick_cache_items(maxsize, ttl):
        items = list(cache.items())
        expired_items = [_item for _key, _item in items if _item['expiry'] <= timer()]
        items = sorted(items, key=lambda x: x['expiry']) if expired_items else items
        return items[:maxsize]

    def _wrap_func(func):
        cache = {}
        keys_list = []

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _get_key(*args, **kwargs)
            cached_value = _cache(func, cache, key)
            if cached_value is not None:
                return cached_value
            result = func(*args, **kwargs)
            if _get_key(*args, **kwargs) in keys_list:
                _mark_obsolete(keys_list)
            keys_list.append(_get_key(*args, **kwargs))
            if len(keys_list) > maxSize:
                keys_list = _affected_keys(keys_list)
            return result

        @functools.wraps(wrapper)
        def clear_cache():
            _clear_cache(keys_list)
            cache.clear()

        @functools.wraps(wrapper)
        def put(*args, **kwargs):
            key = _get_key(*args, **kwargs)
            _put_cache(func, cache, key, wrapper(*args, **kwargs))

        @functools.wraps(wrapper)
        def forget(*args, **kwargs):
            key = _get_key(*args, **kwargs)
            if _cache(func, cache, key) is not None:
                _put_cache(func, cache, key, None)

        wrapper.clear_cache = clear_cache
        wrapper.put = put
        wrapper.forget = forget
        wrapper.cache = cache
        wrapper.keys_list = keys_list
        return wrapper

    return _wrap_func(func)

