def _lazy_eval(fn):
    """Lazy evaluate an associative (not commutative) function."""
    caches = [OrderedDict()]
    ops = ['+', '-', '*', '^', '//', '/' if fn.__name__.startswith('op:__') else None]
    def next_cache(seq):
        nonlocal caches
        if caches[-1] == {} or not seq or len(seq) != len(caches[-1]):
            caches.append(OrderedDict())
        return caches[-1]
    def next_op(i):
        nonlocal ops
        if ops:
            return ops.pop(0)
        return None
    class LRU2:
        def __init__(self, op, a, b):
            self.cache = reduce(next_cache)([a, b])
            self.op = next_op(i)
            self.a = a
            self.b = b
        def __call__(self):
            key = (self.a, self.b)
            if key not in self.cache:
                self.cache[key] = self.op(self.a, self.b)
            return self.cache[key]
    return reduce(next_cache)([fn(a, b) for a, b in zip(range(len(args)), args)]) if len(args) > 1 else LRU2(next_op(0), args[0], args[1])

