            def wrapper(*args, **kwargs):
                key = _rfu((args, kwargs))
                if key == 0:  # miss
                    return func(*args, **kwargs)
                else:  # hit
                    return func(*args, **kwargs)

            wrapper.hits = hits
            wrapper.misses = misses
            return wrapper

        return decorator

