    """
    Write to the specified filename, the provided binary buffer
    Create the file if required.
    :param file_name:  File name.
    :type file_name: str
    :param text_buffer: Text buffer to write.
    :type text_buffer: str
    :param encoding: The encoding to use.
    :type encoding: str
    :param overwrite: If true, file is overwritten.
    :type overwrite: bool
    :return: The number of bytes written or lt 0 if error.
    :rtype int
    """
    assert isinstance(text_buffer, str)
    assert overwrite in [True, False]

    if overwrite:
        try:
            with open(file_name, 'w', encoding=encoding) as file:
                file.write(text_buffer)
                return len(text_buffer)
        except IOError as e:
            LOGGER.error("Error writing to file {}: {}".format(file_name, e))
            return -1
    else:
        try:
            with open(file_name, 'r', encoding=encoding) as file:
                existing_content = file.read()
            if text_buffer != existing_content:
                try:
                    with open(file_name, 'w', encoding=encoding) as file:
                        file.write(text_buffer)
                        return len(text_buffer)
                except IOError as e:
                    LOGGER.error("Error writing to file {}: {}".format(file_name, e))
                    return -1
            else:
                LOGGER.info("No change to file {}".format(file_name))
                return 0
        except IOError as e:
            LOGGER.error("Error reading from file {}: {}".format(file_name, e))
            return -1

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    # Open the file in binary write mode
    with open(file_name, 'wb' if overwrite else 'ab') as file:
        # Write the text buffer to the file
        file.write(text_buffer.encode(encoding))
    return file.tell()

