def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        d_result = {}
        for k, v in d1.items():
            if k not in d2:
                d_result[k] = v
            elif isinstance(v, dict):
                d1_new = difference(v, d2.get(k, {}), level=level)
                if d1_new:
                    d_result[k] = d1_new
            else:
                if v != d2.get(k, {}):
                    d_result[k] = v
        return d_result
    elif level > 0:
        return {k: v for k, v in d1.items() if k not in d2 or not d1[k].items() >= d2[k].items()[:level]}
    else:
        return {}

def difference(d1, d2, level=-1):
    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif level != -1:
            d1_alias = d1 if isinstance(d1, dict) else d1.__dict__
            d2_alias = d2 if isinstance(d2, dict) else d2.__dict__
            if not isinstance(d1_alias.get(key), dict) and not isinstance(d2_alias.get(key), dict):
                diff[key] = d1[key]
            elif level == 1 and key in d2 and (d1.get(key) != d2.get(key)):
                diff[key] = d1[key]
            elif level > 1:
                diff_changes = difference(d1[key], d2[key], level - 1).items()
                for subkey, subval in diff_changes:
                    diff['{}.{}'.format(key, subkey)] = subval
    return diff

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if not isinstance(coord, np.ndarray) or coord.size != 2:
            raise ValueError("coord must be a 2D numpy array")
        if not np.isscalar(weight):
            raise ValueError("weight must be a scalar")

        x, y = coord
        if x < self.edges[0] or x > self.edges[-1] or y < self.edges[0] or y > self.edges[-1]:
            return

        bin_x_index = int((x - self.edges[0]) / self.bin_size)
        bin_y_index = int((y - self.edges[0]) / self.bin_size)

        if 0 <= bin_x_index < self.n_bins and 0 <= bin_y_index < self.n_bins:
            self.values[bin_x_index, bin_y_index] += weight

def fill(self, coord, weight=1):  # noqa: D211
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("coord must be a tuple of length 2")
    if not isinstance(weight, (int, float)):
        raise ValueError("weight must be a number")

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, np.ndarray):
        coord = np.array(coord)

    if not isinstance(weight, (int, float)) or weight <= 0:
        raise ValueError("Weight must be a positive numeric value")

    if not hasattr(self, 'data'):
        raise ValueError("Histogram not initialized")

    if len(coord) != len(self.data):
        raise ValueError("Number of coordinates and weights must match histograms dimensions")

    for i in range(len(coord)):
        x, y = map(int, coord[i])

        if x < 0 or y < 0 or x >= self.data.shape[0] or y >= self.data.shape[1]:
            continue

        self.data[y, x] += weight

