class Schema:
    def __init__(self, type: str, default: Any = None):
        self.type = type
        self.default = default

class Array:
    def __init__(self, contained_type: Schema):
        self.contained_type = contained_type

class Application:
    def __init__(self, manifest: Dict[str, str]):
        self.manifest = manifest

class DefaultObserverSchema:
    def __init__(self, application: Application):
        self.application = application
        self.resource_specs = self._extract_resource_specs()

    def _extract_resource_specs(self) -> Dict[str, Any]:
        resource_specs = {}
        for name, spec in self.application.manifest.items():
            resource_specs[name] = {
                'type': 'json',
                'default': {
                    'kind': name,
                    'metadata': {
                        'apiVersion': 'k8s.io/api/v1',
                        'name': spec['name']
                    }
                }
            }
        return resource_specs

    def generate_schema(self) -> Dict[str, Any]:
        schema = {}
        for resource_name, spec in self.resource_specs.items():
            schema[resource_name] = spec
        return schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}

    # Iterate over each manifest in the application
    for manifest in app.spec.manifest:
        resource_name = manifest['apiVersion'] + '/' + manifest['kind']
        if resource_name not in default_schemas:
            # Create a default observer schema based on the resource and app context
            default_schemas[resource_name] = {
                'type': 'object',
                'properties': {
                    'status': {'type': 'string'}
                },
                'additionalProperties': False
            }

    return default_schemas

