    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Ensure the query is compatible with the out-style parameter style
    if self._sql_params.in_style == 'named':
        if isinstance(params, dict):
            formatted_dict = {self._sql_params.name_map[p.lower()]: value for p, value in params.items()}
        else:
            formatted_dict = {self._sql_params.name_map[p.lower()]: value for p, value in enumerate(params)}

            # Convert the dictionary to a list of tuples
            formatted_dict = list(formatted_dict.items())
    else:
        if isinstance(params, tuple):
            formatted_list = list(params)
        else:
            formatted_list = list(enumerate(params))

            # Convert the list of tuples to a dictionary
            formatted_list = dict(formatted_list)

    return sql, formatted_list

def format(self, sql: str | bytes, params: dict[str, Any] | list[Any]) -> Tuple[str | bytes, dict[str, Any] | list[Any]]:
    if self.SQLParams.in_style == 'named':
        if not isinstance(params, dict):
            raise ValueError('params should be a dictionary if SQLParams.in_style is "named"')
    elif self.SQLParams.in_style == 'ordinal':
        if not isinstance(params, list) or len(params) != len(self.get_inplace_params()):
            raise ValueError('params should be a list of values if SQLParams.in_style is "ordinal"')
    else:
        raise ValueError('SQLParams.in_style should be either "named" or "ordinal"')

    if isinstance(params, list):
        # Convert list of values to list of dictionaries for ordinal style
        out_params = []
        for value in params:
            out_params.append({self.get_inplace_params()[i]: value} for i in range(len(self.get_inplace_params())))
    else:
        out_params = params

    formatted_sql = sql % {key: value for key, value in out_params.items()}
    return formatted_sql, out_params

