def files_list(path: str) -> List[str]:
    ret = []
    if exists(path):
        if isfile(path):
            ret.append(abspath(path))
        elif isdir(path):
            for root, dirs, files in os.walk(path, topdown=True):
                for name in files:
                    ret.append(join(root, name))
        else:
            raise File404(path)
    return ret

