    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def try_expr_add(expr, expr2):
        if expr != 0 and expr2 != 0 and self.absorption(x, expr, expr2):
            return expr | expr2
        else:
            return expr

    absorbs = set(args)
    negatives = set(args)

    for expr in args:
        if isinstance(expr, tuple):
            remains, negate = expr
            new_expr = try_expr_add(remains, negate)
            if new_expr:
                absorbs.add(new_expr)
                negatives.add(remains)
                negatives.add(negate)
                try_expr_add(self.absorb(negate), new_expr)
        else:
            if expr == 0 or expr in negatives:
                absorbs.add(expr)
            if expr in absorbs:
                negatives.add(expr)

    return(list(absorbs - negatives))

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorb(expr1, expr2):
        if expr1 == expr2:
            return expr1
        elif expr1 == 'A' and expr2 == 'A':
            return 'A'
        elif expr1 == 'A' and expr2 == 'B':
            return expr2
        elif expr1 == 'B' and expr2 == 'A':
            return expr2
        elif expr1 == 'B' and expr2 == 'A':
            return expr2
        else:
            return 'None'

    abs_list = []
    neg_abs_list = []
    for expr in args:
        if expr[0] == '+':
            if ' & ' in expr:
                left, right = expr.split(' & ')
                abs_list.append(absorb(left, right))
            elif ' | ' in expr:
                left, right = expr.split(' | ')
                neg_abs_list.append(absorb(left, right))
        else:
            abs_list.append('A')
            neg_abs_list.append('A')

    return abs_list + neg_abs_list

