        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if dt.tzinfo is None:
            raise ValueError("datetime must be timezone-aware")
        tzinfo = dt.tzinfo
        offset = tzinfo.utcoffset(None)
        if offset is None:
            raise ValueError("cannot determine an offset for timezone {0}".format(tzinfo))

        # Calculate the new time offset for the new timezone
        new_offset = self.new_timezone_offset(dt)

        # Calculate the new time for the new timezone
        new_time = dt.replace(tzinfo=self.new_timezone(), year=dt.year, month=dt.month, day=dt.day, hour=dt.hour, minute=dt.minute, second=dt.second, microsecond=dt.microsecond)

        # Calculate the new date for the new timezone
        new_date = dt.replace(tzinfo=self.new_timezone(), year=dt.year, month=dt.month, day=dt.day)

        # Calculate if the new time is ambiguous or in a "fold" state
        if new_time.year < new_date.year:
            new_time = new_time.replace(year=new_date.year + 1)
        elif new_time/year == new_date/year:
            if new_time.month < new_date.month:
                new_time = new_time.replace(year=new_date.year, month=new_date.month + 1)
            elif new_time.month == new_date.month:
                if new_time.day < new_date.day:
                    new_time = new_time.replace(year=new_date.year, month=new_date.month, day=new_date.day + 1)
                elif new_time.day == new_date.day:
                    if new_time.hour < new_date.hour:
                        new_time = new_time.replace(year=new_date.year, month=new_date.month, day=new_date.day, hour=new_date.hour + 1)
                    elif new_time.hour == new_date.hour:
                        if new_time.minute < new_date.minute:
                            new_time = new_time.replace(year=new_date.year, month=new_date.month, day=new_date.day, hour=new_date.hour, minute=new_date.minute + 1)
                        elif new_time.minute == new_date.minute:
                            if new_time.second < new_date.second:
                                new_time = new_time.replace(year=new_date.year, month=new_date.month, day=new_date.day, hour=new_date.hour, minute=new_date.minute, second=new_date.second + 1)
                            elif new_time.second == new_date.second:
                                if new_time.microsecond < new_date.microsecond:
                                    new_time = new_time.replace(year=new_date.year, month=new_date.month, day=new_date.day, hour=new_date.hour, minute=new_date.minute, second=new_date.second, microsecond=new_date.microsecond + 1)
                                # Return ambiguous time representation
                                return (
                                    datetime(year=new_time.year, month=new_time.month, day=new_time.day, hour=new_time.hour, minute=new_time.minute, second=new_time.second, microsecond=new_time.microsecond, tzinfo=self.new_timezone()),
                                    True
                                )
        return (new_time, False)

