import operator

class RecursiveNormalizer:
    def __init__(self, recursive=True):
        self.recursive = recursive

    def _to_fields(self, value):
        # Temporary cache for the result to avoid infinite loop
        if id(value) in self._to_fields_cache:
            return self._to_fields_cache[id(value)]

        if isinstance(value, timedelta):
            if self.recursive and not isinstance(value, RecursiveNormalizer):
                # Create a recursive instance of timedelta
                value = RecursiveNormalizer()(value)
            return (value.total_seconds() / (3600 * 24), operator.mod)
        elif isinstance(value, tuple):
            return tuple(item if self.recursive and not isinstance(item, RecursiveNormalizer) else RecursiveNormalizer()(item) for item in value)
        elif isinstance(value, list):
            return [item if self.recursive and not isinstance(item, RecursiveNormalizer) else RecursiveNormalizer()(item) for item in value]
        elif isinstance(value, dict):
            return {key: RecursiveNormalizer()(value[key]) for key in value}
        else:
            return value

    def normalized(self, value):
        """
        Return a version of this object represented entirely using integer
        values for the relative attributes.

        >>> relativedelta(days=1.5, hours=2).normalized()
        relativedelta(days=+1, hours=+14)

        :return:
           Returns a :class:`dateutil.relativedelta.relativedelta` object.
        """
        self._to_fields_cache = {}

        # Separate the fields from the value
        num_seconds, mod_func = self._to_fields(value)

        # Convert to a timedelta
        delta = timedelta(seconds=num_seconds, microseconds=0)

        # Apply the modulus function
        result = mod_func(delta)

        return result

