def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of command strings to be executed.
    :param args: A list of arguments to be passed to the commands.
    :param cwd: The working directory in which to execute the commands.
    :param verbose: Whether to print stdout and stderr of the commands.
    :param hide_stderr: Whether to hide stderr of the commands.
    :param env: A dictionary of environment variables to be set for the commands.
    """
    if not commands:
        return

    output = ""
    try:
        for cmd in commands:
            if args:
                command = "{} {}".format(cmd, ' '.join(args))
            else:
                command = cmd

            if env:
                result = subprocess.run(command, cwd=cwd, env=env, text=True, capture_output=not verbose)
                output += result.stdout
                if not hide_stderr:
                    output += result.stderr
            else:
                result = subprocess.run(command, cwd=cwd, text=True, capture_output=not verbose)
                output += result.stdout
                if not hide_stderr:
                    output += result.stderr
    except subprocess.CalledProcessError as e:
        output = e.stdout + e.stderr if e.stdout else e.stderr
        raise ExecutableError("bad command execution: " + output)

    return output

