    """Call the given command(s)."""
    try:
        cmds = []
        for command in commands:
            if isinstance(command, list):
                combined_command = [command[0]] + [arg for arg in command[1:] if arg is not None]
            else:
                combined_command = [command]
            cmds.extend(combined_command)
        if env is None:
            env = os.environ.copy()
