class CommandRunner:
    def run_command(self, commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
        """
        Call the given command(s).

        :param commands: The commands to run as strings.
        :param args: The arguments to pass to the commands.
        :param cwd: The working directory.
        :param verbose: Print verbose output.
        :param hide_stderr: Hide stderr output.
        :param env: Environment variables to set.
        """
