            if verbose:
                print(f"Command '{cmd}': {result.stdout}")

            if isinstance(result.stdout, str):
                stdout_text = result.stdout.strip()
            else:
                stdout_text = None

            if isinstance(result.stderr, str):
                stderr_text = result.stderr.strip()
            else:
                stderr_text = None

