def next_version(version: str) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    """
    version_pattern = r'(\d+\.)?\d+(\.\d+)?$'
    match = re.match(version_pattern, version)
    if not match:
        raise ValueError("Invalid version format")

    version_part, separator, increment_count = match.groups()
    if version_part:
        if version_part.startswith('0'):
            adjusted_version_part = '1'
        else:
            adjusted_version_part = str(int(version_part) + 1)
    else:
        adjusted_version_part = '1'

    semi separators = ['.', '-']
    if separator in semi_separators:
        increment_count = int(increment_count) + 1
    else:
        increment_count = int(increment_count)

    adjusted_version = f"{adjusted_version_part}{separator}{increment_count}"
    return adjusted_version

def next_version(version: str) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    :param version: Version string.
    :return: Next version identifier.
    """
    num_digits = len(version) - version.lstrip('0').find('0')

    if num_digits == 0:
        return 1
    elif num_digits == 1 and version.startswith('0'):
        return '10'
    else:
        return str(int(version) + 1)

import packaging.specifiers
from distutils.core import Distribution, DistutilsSetupError

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version in version_dirs:
        try:
            packaging.specifiers.SpecifierSet(version)
        except packaging.specifiers.InvalidSpecifier as error:
            tmpl = (
                "version specifier for '{}' should be a string "
                "containing valid version specifiers; {error}"
            )
            raise DistutilsSetupError(tmpl.format(version, error))

    # Check for duplicate version configurations
    inventory_versionings = []
    for version_dir in version_dirs:
        inventory_rst = os.path.join(version_dir, "..", "..", "products", "build", "releases", "versions", f"{version}.rst")
        with open(inventory_rst, 'r') as h:
            inventory_versioning = packaging.specifiers.SpecifierSet(h.read().strip())
            inventory_versionings.append(inventory_versioning)

    for verd, invgen in enumerate(inventory_versionings[:-1]):
        for vend, invgen2 in enumerate(inventory_versionings[verd + 1:]:
            if invgen != invgen2:
                self.check_distubution_conflict("versions", "{verd}:{vend}", invgen, invgen2, path)

def check_distubution_conflict(self, doc1, doc2, spec1, spec2, path):
    """Check if the passed specifiers conflict with the current specifiers in the distribution."""
    curr_spec = self.metadata['version']
    if spec1 == spec2:
        return
    if spec1 and spec1 < curr_spec:
        if not self.has_file(path):
            return
        spec2_divided = str(spec2)[:len(str(spec1))]
        if spec2_divided == str(spec1):
            for verb, verb2 in [('install_requiresversion', 'install_requiresversion'),
                                ('provides', 'provides'),
                                ('requires', 'requires'),
                                ('optdepends', 'optdepends'),
                                ('conflicts', 'conflicts')]:
                key = verb.lower() + verb2.lower()
                if key in self.metadata and spec2_divided in self.metadata[key]:
                    raise ValueError(f'Conflicting versions for {key} in {doc1} and {doc2}')
                    return
    if spec2 == spec1:
        return
    if spec3 and spec3 < curr_spec:
        spec3_divided = str(spec3)[:len(str(spec2))]
        if spec3_divided == str(spec2):
            for verb, verb2 in [('install_requiresversion', 'install_requiresversion'),
                                ('provides', 'provides'),
                                ('requires', 'requires'),
                                ('optdepends', 'optdepends'),
                                ('conflicts', 'conflicts')]:
                key = verb.lower() + verb2.lower()
                if key in self.metadata and spec3_divided in self.metadata[key]:
                    raise ValueError(f'Conflicting versions for {key} in {doc2} and {doc3}')
                    return
    self.check_distubution_conflict(doc1, doc3, spec1, spec2, path)

