def find_path_type(path):
    if path.endswith('0=*'):
        return 'root'
    elif path.startswith('0=1OCFL Object/'):
        return 'object'
    elif path.startswith('0=1OCFL Inventory/'):
        return 'file'
    else:
        return 'unknown type'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    if not path:
        return "Invalid input: Path cannot be empty."

    if not path.endswith('/'):
        path += '/'

    if not path.startswith('/'):
        path = '/' + path

    container_type = 'other'
    prefix = '0='

    with open(path, 'r') as file:
        for line in file:
            if line.strip().startswith(prefix):
                container_type = line.split('=')[1].strip()
                break

    if container_type in ['0=storage-root', '0=object']:
        return container_type

    if container_type in ['0=bag', '0=baginfo', '0=bagit']:
        return 'object'

    if container_type == '0=file':
        return 'file'

    return f"Invalid path type: {container_type}"

