def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    argument_parsers = {subparser.name: subparser for subparser in subparsers.values()}

    parsed_arguments = {}
    remaining_arguments = []

    for arg in unparsed_arguments:
        if not arg.startswith('--'):
            remaining_arguments.append(arg)
            continue

        short_arg = arg[2:]
        long_arg = arg

        for name, parser in argument_parsers.items():
            if parser.short_help_short == short_arg or parser.long_help_short == long_arg:
                try:
                    # Try to parse the argument with the subparser
                    namespace = parser.parse_known_args([arg])[0]
                    parsed_arguments[name] = namespace
                except Exception as e:
                    # If parsing fails, print an error message and continue
                    print(f"Error parsing {arg} for {name}: {e}")
            elif parser.short_help_long == short_arg or parser.long_help_long == long_arg:
                try:
                    # Try to parse the argument with the subparser
                    namespace = parser.parse_known_args([arg])[0]
                    parsed_arguments[name] = namespace
                except Exception as e:
                    # If parsing fails, print an error message and continue
                    print(f"Error parsing {arg} for {name}: {e}")

    return parsed_arguments, remaining_arguments

