class Node:
    def __init__(self, value):
        self.value = value
        self.links = []

class MergeError(Exception):
    def __init__(self, message, conflicts):
        self.message = message
        self.conflicts = conflicts

class NodeMerger:
    def __init__(self, node):
        self.node = node

    def deep_merge(self):
        self._merge()
        return self.node

    def _merge(self):
        visited = set()
        stack = [self.node]
        while stack:
            for node in stack:
                if node.value in visited:
                    continue
                visited.add(node.value)
                if isinstance(node, Node):
                    for link in node.links:
                        if link.node.value == node.value:
                            link.node.value = self._merge_node(link.node, visited, stack)
                            break
                elif isinstance(node, list):
                    for item in node:
                        if isinstance(item, Node):
                            for link in item.links:
                                if link.node.value == item.value:
                                    link.node.value = self._merge_node(link.node, visited, stack)
                                    break

    def _merge_node(self, node, visited, stack):
        new_node = Node(node.value)
        new_node.links.extend(node.links)
        stack.append(new_node)
        return new_node

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_nodes = {}
    seen_keys = set()

    def merge_node(node, parent_key):
        if isinstance(node, ruamel.yaml.nodes.MappingNode):
            for key, value in node.items():
                if key in seen_keys:
                    if isinstance(value, ruamel.yaml.nodes.MappingNode):
                        merged_value = merge_node(value, parent_key + (key,))
                    else:
                        merged_value = value
                else:
                    seen_keys.add(key)
                    merged_value = merge_node(value, parent_key + (key,))
                merged_nodes[key] = merged_value
        elif isinstance(node, ruamel.yaml.nodes.ScalarNode):
            if parent_key in merged_nodes:
                if isinstance(merged_nodes[parent_key], ruamel.yaml.nodes.MappingNode):
                    merged_nodes[parent_key][node.tag] = node.value
                else:
                    merged_nodes[parent_key] = ruamel.yaml.nodes.MappingNode(tag=node.tag)
                    merged_nodes[parent_key][node.tag] = node.value
            else:
                merged_nodes[parent_key] = node.value

    for key, value in nodes:
        merge_node(value, key)

    return list(merged_nodes.items())

def deep_merge_nodes(nodes):
    merged = {}
    for key, value in nodes:
        if key in merged:
            if isinstance(merged[key], dict) and isinstance(value, dict):
                merged[key] = deep_merge_nodes([(key, value)])
            elif merged[key] == value:
                pass
            else:
                merged[key] = {**merged[key], **value}
        else:
            merged[key] = value
    return list(merged.items())

