class OrderedHyphenDict(OrderedDict):
    """Extends OrderedDict with hyphens as keys"""
    def __init__(self, *args, **kwargs):
        super(OrderedHyphenDict, self).__init__(*args, **kwargs)
        for key, value in self.items():
            self[key] = self.from_string(value)

    @staticmethod
    def from_string(string):
        """Converts string to integer if it is a number"""
        try:
            return int(string)
        except ValueError:
            pass
        try:
            return float(string)
        except ValueError:
            pass
        return string

def _replace_url_args(url, url_args):
    if not url or not url_args:
        return url

    parts = urllib.parse.urlparse(url)
    query_params = urllib.parse.parse_qs(parts.query)

    for key, value in url_args.items():
        existing_value = query_params.get(key, [None])[0]
        if existing_value is not None:
            query_params[key] = value
        else:
            query_params[key] = value

    new_query = urllib.parse.urlencode(query_params, doseq=True)
    new_parts = parts._replace(query=new_query)
    return urllib.parse.urlunparse(new_parts)

