        return True

    processed.add(abs_path)
    return False

def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    if not isinstance(vertices, list) or len(vertices) != 3:
        raise ValueError("Expected a list of 3 vertices")
    try:
        side_a = vertices[1] - vertices[0]
        side_b = vertices[2] - vertices[1]
        return (vertices[0], vertices[0] + side_a, vertices[0] + side_a + side_b)
    except AttributeError:
        raise ValueError("Vertices must be of type Point")

def vertex3tuple(vertices):
    vertices = sorted(vertices, key=lambda v: v.x, reverse=True)
    result = []
    for i in range(len(vertices)):
        result.extend([(vertices[i], vertices[(i-1) % len(vertices)], vertices[(i+1) % len(vertices)])])
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        # Handle negative numbers separately
        return "-" + int_to_string(-number, alphabet, padding)

    if padding is not None:
        # Add leading zeros if necessary
        if len(str(number)) < padding:
            return '0' * (padding - len(str(number))) + str(number)

    result = ''
    index = len(alphabet) - 1
    while number and index >= 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)
        index -= 1

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return '0'

    if padding is None:
        padding = max(1, len(alphabet)) * 2

    res = []
    while number > 0:
        char = alphabet[number % len(alphabet)]
        res.append(char)
        number //= len(alphabet)

    res.reverse()
    if len(res) < padding:
        res = ['0'] * (padding - len(res)) + res

    return ''.join(res)

