def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

        seen.remove(cls)
    return seen

