from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    n = 0
    for i, char in enumerate(reversed(string)):
        n += alphabet.index(char) * (len(alphabet) ** i)
    return n

from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    base = len(alphabet)
    inverse_alphabet = {char: i for i, char in enumerate(alphabet)}
    n = 0
    exp = 0
    for i in reversed(string):
        n += inverse_alphabet[i] * (base ** exp)
        exp += 1

    return n

