              0 = Windows/CMD
              (other values reserved)
    """
    re_splitflags = {
        'this': re.UNICODE + re.MULTILINE,
        1: re.UNICODE + re.XMATCH + re.MULTILINE,
        0: re.UNICODE + re.XMATCH
    }

    # Get the appropriate flags for the specified platform
    platform_flags = re_splitflags.get(platform, re.UNICODE + re.MULTILINE)

    # Split the string using the appropriate flags
    return re.findall(r'\s*(?:[^\'"]|' + \\r\\n')*\s*[\'"]([^\'"]+?)[\'"]?\s*', s, flags=platform_flags)

