import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name
    elif platform != 0 and platform != 1:
        raise ValueError("Unsupported platform. Supported platforms are 'this' (auto), 1 (POSIX), and 0 (Windows/CMD).")

    if platform == 'posix':
        return re.split(r'(?<!\\)([^\s\'"\\])\s*(["\']([^\"]|\\")*)',
                        s, flags=re.DOTALL)
    elif platform == 0:
        return re.split(r'(?<!\\)([^\s\'"\\])\s*(["\']([^\"]|\\")*)',
                        s, flags=re.DOTALL)

