def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError("Archive not found at {}".format(archive_path))

    if filename:
        input_file = filename
    else:
        input_file = os.path.basename(archive_path)

    output_file = os.path.join(tmp_path, input_file)
    subprocess.run(['unzip', archive_path, '-o', output_file], check=True)

    return 'file://{}'.format(os.path.abspath(output_file))

