def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    try:
        if isinstance(commands, str):
            commands = [commands]

        command_args = []
        for c, a in zip(commands, args):
            if isinstance(a, list):
                command_args.append(f"{c} {' '.join(a)}")
            else:
                command_args.append(f"{c} {a}")

        command_str = ' '.join(command_args)
        process = subprocess.Popen(command_str, shell=True, cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

        if verbose:
            print(f"Running command: {command_str}")

        if not hide_stderr:
            print(f"Error output: {process.stderr.read().decode()}")

        stdout = process.stdout.read().decode()
        stderr = process.stderr.read().decode()

        if verbose:
            print(f"Standard output: {stdout}")
            print(f"Standard error: {stderr}")

        return stdout, stderr
    except Exception as e:
        raise ProgramError(e)

