from collections import OrderedDict

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        supported_protocols = OrderedDict()
        for protocol_version, handlers in cls.__supported_protocols.items():
            supported_protocols[protocol_version] = handlers
        return supported_protocols
    elif isinstance(protocol_version, tuple):
        protocol_version = tuple(int(v) for v in protocol_version)
        if protocol_version not in cls._supported_protocols:
            raise ValueError(f'Protocol version {protocol_version} is not supported')
        return {protocol_version: cls._supported_protocols[protocol_version]}
    else:
        raise TypeError('protocol_version must be a tuple or None')

def protocol_handlers(cls, protocol_version=None):
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version should be a tuple identifying a specific protocol version")

    handlers = {}
    for version in range(1, 17):  # Protocol versions 1 to 16
        handler_class = f"bolt.{version}Handler"
        if hasattr(cls, handler_class):
            handlers[version] = getattr(cls, handler_class)

    supported_versions = list(handlers.keys())
    return supported_versions if protocol_version is None else [version for version in supported_versions if version == protocol_version]

