def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    elif isinstance(seq, set):
        return sorted(seq), type(seq)
    elif isinstance(seq, dict):
        return sorted([(key, val) for key, val in seq.items()], key=lambda x: x[0]), type(seq)
    elif isinstance(seq, bytes):
        return seq.decode('utf-8'), type(seq)
    elif isinstance(seq, str):
        return seq.encode('utf-8'), type(seq)
    else:
        raise TypeError("Unexpected type for seq: %s" % type(seq))

def _get_seq_with_type(seq, bufsize=None):
    if isinstance(seq, list):
        return (seq, 'list')
    elif isinstance(seq, tuple):
        return (seq, 'tuple')
    elif isinstance(seq, str) and bufsize is not None:
        from io import BytesIO
        # Convert string to bytes, read into a buffer of bufsize size
        # Each element of the buffer will be a byte read from the string,
        # until the buffer is empty.
        buffered = BytesIO(seq.encode('utf-8'))
        chunks = []
        while True:
            value = buffered.read(bufsize)
            if not value:
                break
            chunks.append(value)
        return (chunks, 'buffered string')
    elif isinstance(seq, bytes):
        if bufsize is not None:
            from io import BytesIO
            buffered = BytesIO(seq)
            chunks = []
            while True:
                value = buffered.read(bufsize)
                if not value:
                    break
                chunks.append(value)
            return (chunks, 'buffered bytes')
        else:
            return (list(seq), 'byte array')
    else:
        return (seq, 'not a sequence')

