from inspect import getfullargspec

def _verify(iface, candidate, tentative=False, vtype=None):
    results = []
    errors = []

    # Step 1: Each candidate must claim to provide the interface
    try:
        if tentative:
            imposters = [candidate.__call__()] + list(candidate.__dict__.values())
            for obj in imposters:
                if obj.providedBy if hasattr(obj, 'providedBy') else \
                    obj.implements if hasattr(obj, 'implements') else \
                    obj.provides if hasattr(obj, 'provides'):
                    results.append(obj)
                    break
            else:
                raise Invalid("Candidate does not claim to provide the interface")
        else:
            results.append(iface.providedBy(candidate))
    except Exception as e:
        errors.append(f"Failed to check if candidate provides iface: {e}")

    # Step 2: Each candidate must define all the necessary methods
    for meth_name, meth in getfullargspec(candidate).args + getfullargspec(candidate).keywords:
        try:
            getattr(candidate, meth_name)
        except Exception as e:
            errors.append(f"Failed to find method {meth_name}: {e}")

    # Step 3: Each candidate must define all the necessary attributes
    for attr_name in getfullargspec(candidate).args + getfullargspec(candidate).keywords:
        try:
            getattr(candidate, attr_name)
        except Exception as e:
            errors.append(f"Failed to find attribute {attr_name}: {e}")

    # If no errors were found, return true. But if errors were found,
    # concatenate all the error messages into a single string and raise an Invalid exception.
    if not errors:
        return True
    else:
        errors_str = '\n'.join(errors)
        raise Invalid(f"Verification failed: \n{errors_str}")

