import inspect

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # Check for conformity to the providedBy interface
    if tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not follow the providedBy interface.")
        for provided_interface in iface.providedBy(candidate):
            if not isinstance(provided_interface, type):
                errors.append(f"Type for provided interface: {provided_interface} is not a Zope interface.")
    else:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}.")
        for provided_interface in iface.providedBy(candidate):
            if not issubclass(provided_interface, type(candidate)):
                errors.append(f"Concrete class provided does not belong to interface.")  # pragma: no cover

    # Check for complete methods and attributes
    for method in inspect.getmembers(candidate, inspect.isfunction):
        if method[0] != "__init__":
            iface.verifyCallable(candidate, method[0], vtype=vtype, errors=errors)
    for attr in inspect.getmembers(candidate, lambda x: isinstance(x, str)):
        if attr[0] != "__name__":
            iface.verifyProvided(candidate, attr[0], errors=errors)
    for attr in inspect.getmembers(candidate, lambda x: isinstance(x, str)):
        iface.verifyImplemented(candidate, attr[0], errors=errors)

    # Raise errors if any were found
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid("; ".join([error.message for error in errors]))
    return True

