def identify_request(request: RequestType) -> bool:
    """ Try to identify whether this is a Matrix request

    :param request: :class:`RequestType`: A matrix HTTP request object
    :return: bool: True if this is a Matrix request, False otherwise.

    """

    if request.method not in ["POST", "PUT", "DELETE"]:
        raise ValueError("Request method must be POST, PUT, or DELETE")

    if not request.headers.get("Authorization"):
        return False

    try:
        request_json = json.loads(request.body.decode('utf-8'))
    except json.JSONDecodeError:
        return False

    return "matrix" in request_json.get("type", "")

