def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
        """Find tags in text.

        Tries to ignore tags inside code blocks.

        Optionally, if passed a "replacer", will also replace the tag word with the result
        of the replacer function called with the tag word.

        Returns a set of tags and the original or replaced text.
        """

        tags_enclosed_in_code_block = False
        all_tags = set()
        current_tag = None

        lines = text.split('\n')
        for line in lines:
            if codeblock_marker in line:
                tags_enclosed_in_code_block = not tags_enclosed_in_code_block

            if not tags_enclosed_in_code_block and tag_marker in line:
                tag_pos = line.find(tag_marker)
                if tag_pos != -1:
                    tag = line[tag_pos + 1:].strip()
                    tags_enclosed_in_code_block = True
                    current_tag = tag
                    continue

            if tags_enclosed_in_code_block and tag_marker in line:
                tag_pos = line.find(tag_marker)
                if tag_pos != -1:
                    tag = line[tag_pos + 1:].strip()
                    all_tags.add(tag)
                    tags_enclosed_in_code_block = False

            if tags_enclosed_in_code_block or tag_pos == -1:
                current_tag = None

            if current_tag and replacer:
                replace_with = replacer(current_tag)
                if replace_with:
                    replaced_line = line.replace(tag_marker + current_tag, tag_marker + replace_with)
                    all_tags.add(replace_with)
                else:
                    replaced_line = line
            else:
                replaced_line = line

            if replaced_line != line:
                all_tags.add(replaced_line)

        replaced_text = '\n'.join(all_tags)
        return all_tags, replaced_text


