def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    :param settings_dirs: Directory or list of directories where the ini files are located
    :param spec_option: Type of specification option to build
    """

    if not isinstance(settings_dirs, list):
        settings_dirs = [settings_dirs]

    file_names = []
    for directory in settings_dirs:
        if not os.path.exists(directory):
            raise FileNotFoundError(f"Directory not found: {directory}")
        for filename in os.listdir(directory):
            if filename.endswith('.ini'):
                file_names.append(os.path.join(directory, filename))

    return sorted(file_names)

