def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Args:
        settings_dirs (list): Directories containing settings files
        spec_option (str): Specification option to identify the specific template

    Returns:
        list: List of file names
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list of directories")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    files = []
    for directory in settings_dirs:
        if not os.path.exists(directory):
            raise FileNotFoundError(f"Directory {directory} does not exist")
        files.extend([
            os.path.join(directory, file)
            for file in os.listdir(directory)
            if file.endswith('.ini')
        ])

    if not files:
        raise FileNotFoundError("No ini files found in any of the specified directories")
    return files

