import yaml

class IRValidatorException(Exception):
    pass

def validate_from_content(spec_content=None):
    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec = yaml.safe_load(spec_content)
        required_fields = set(spec.keys())
        missing_fields = required_fields - set(spec.values())

        if missing_fields:
            raise IRValidatorException("Missing required fields: {}".format(', '.join(missing_fields)))

        return spec
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid specification format: " + str(e))

