class ValidationMessage:
    def __init__(self, file: str, message: str):
        self.file = file
        self.message = message


class IRValidatorException(Exception):
    """Custom exception to handle validation errors."""
    pass


class Validator:
    def __init__(self, default_schema_file: str, additional_info_schema: str):
        self.default_schema_file = default_schema_file
        self.additional_info_schema = additional_info_schema
        self.validation_messages = []

    def load_custom_schema(self, type: str) -> dict:
        schema_path = f"{type}/schema.json"  # Assuming custom schemas are structured like {'type': 'some_type', 'schema': {...}}
        with open(schema_path, 'r') as f:
            return json.load(f)

    def add_validation_message(self, message: ValidationMessage):
        self.validation_messages.append(message)

    def has_errors(self, file_path: str) -> bool:
        return any(message.file == file_path for message in self.validation_messages)

    @classmethod
    def validate_from_file(cls, yaml_file: Optional[str] = None):
        if yaml_file is None:
            raise LookupError("yaml_file argument must be supplied")

        try:
            yaml_file = Path(yaml_file)
            with yaml_file.open() as f:
                data = yaml.load(f)

            schema_path = "common/schema.json"
            with open(schema_path, 'r') as f:
                schema = json.load(f)

            jsonschema.validate(data, schema)

        except ValidationError as ve:
            message = ValidationMessage(file=yaml_file, message=ve.message)
            cls().add_validation_message(message)
            raise IRValidatorException("Validation failed", message=ve)

        return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """
        Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, 'r') as file:
                yml_dict = yaml.safe_load(file)

            # Check for required fields
            if 'data' not in yml_dict:
                raise IRValidatorException("Mandatory field 'data' is missing")
            if 'type' not in yml_dict['data']:
                raise IRValidatorException("Mandatory subfield 'type' is missing")

            # Validate the data against the schema
            cls.validate_schema(yml_dict['data']['type'], yml_dict['data'])

            return yml_dict

        except OSError as e:
            raise IRValidatorException(f"Failed to open file: {e}")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Failed to parse YAML: {e}")

