def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'groups' not in parser_dict or not parser_dict['groups']:
        return parser_dict
    groups = []
    for spec in parser_dict['groups']:
        spec_dict = self._load_content(spec)
        if 'groups' in spec_dict and spec_dict['groups']:
            groups.extend(self._include_groups(spec_dict))
        else:
            groups.append(spec_dict)
    parser_dict['groups'] = groups
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    def resolve_include_key(key, strip=True):
        if ':' in key:
            key, platform = key.split(':', 1)
        else:
            platform = 'all'

        if strip:
            key = key.split('-', 1)[-1]

        return platform, key

    include_dict = parser_dict.get('include', {})
    included_result = {}
    parser_dict['include'] = included_result

    for include_key, include_value in iteritems(include_dict):
        parser, context = resolve_include_key(include_key)
        if parser in parser_dict:
            if 'parser_params' not in parser_dict[parser]:
                parser_dict[parser]['parser_params'] = []
            parser_dict[parser]['parser_params'].append(include_value)
        else:
            included_result[include_key] = {
                'parser': parser,
                'include_value': include_value
            }

