def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    if 'spec' in self.__getattribute__("_camgeschw"):
        spec_values = self.__getattribute__("_camgeschw").splitcolon().replace(";", ":").split(",")
        spec_values = [value.strip() for value in spec_values if value]
        spec_defaults |= dict([value.split("=", 1) for value in spec_values if "="])
    return spec_defaults

