import warnings

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_mapping = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
    }
    deprecated_has_been_used = False
    updated_args = {}

    if cli_args:
        for old, new in deprecated_mapping.items():
            if old in cli_args:
                warnings.warn(
                    f"Keyword argument '{old}' has been deprecated in favour "
                    f"of '{new}'. Deprecated argument will be removed in a future version.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )
                updated_args[old] = cli_args.pop(old)

    if answer_file_args:
        for old, new in deprecated_mapping.items():
            if old in answer_file_args:
                warnings.warn(
                    f"Keyword argument '{old}' has been deprecated in favour "
                    f"of '{new}'. Deprecated argument will be removed in a future version.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )
                updated_args[old] = answer_file_args.pop(old)

    if updated_args:
        print("Deprecated arguments have been updated:")
        for arg, value in updated_args.items():
            print(f"{arg}: {value}")
    else:
        print("No deprecated arguments to validate.")

def validate_arg_deprecation(self, cli_args, answer_file_args):
