def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    options = list(self.options.items())
    for key, _ in options:
        if not isinstance(key, str):
            continue
        if key.startswith(f'--{command_name}-'):
            if argument_name is None:
                split_key = key.split('-')
                number = int(split_key[3])
            else:
                split_key = key.split('-')
                number = int(split_key[3]) if argument_name == 'number' else split_key[3]
            return self._raw_options[number]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    spec = {}
    if command_name in self.options:
        spec['command'] = command_name
        spec['arguments'] = self.options[command_name]
    if argument_name in spec.get('arguments', []):
        spec['attribute'] = argument_name
        spec['values'] = spec['arguments'][argument_name]
        spec['default'] = self.options[command_name].get(argument_name)
        spec['type'] = self.type_mappings[spec['values'][0]]
    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    option_spec = self.options.get(command_name)

    if not option_spec:
        raise ValueError(f"No option specification found for command '{command_name}'")

    if argument_name not in option_spec:
        raise ValueError(f"No argument specification found for argument '{argument_name}' for command '{command_name}'")

    return option_spec[argument_name]

