def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        if not isinstance(args, dict) and not isinstance(args, list):
            raise TypeError("Arguments must be a dict or a list")

        if isinstance(args, list):
            for arg in args:
                length = self.validate_length(arg)
                if length is None:
                    return False
        else:
            for argname, value in args.items():
                length = self.validate_length(value)
                if length is None:
                    return False

        return True

    def validate_length(self, value):
        """Get the length of a value.

        :param value: The value to get the length of.

        :return: The length of the value, or None if the value is not of type int.
        """
        if isinstance(value, int):
            return value
        elif isinstance(value, str) or isinstance(value, bytes):
            return len(value)
        elif isinstance(value, list) or isinstance(value, tuple):
            return len(value)
        else:
            return None

