import copy

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars:
        var_scopes = vars_dict.copy()
        for var_spec in extra_vars:
            var_spec = dict(var_spec)
            var_name = var_spec.pop('name', None)
            if var_name:
                var_scope = vars_dict.get(var_name, var_spec)
                var_spec.update(var_scope)
                vars_dict[var_name] = var_spec
            else:
                vars_dict.update(copy.deepcopy(var_spec))
            vars_dict = var_scopes

    return vars_dict

import os
import subprocess
import logging

class AnsiblePlaybook:
    def __init__(self, playbook_path, config):
        self.playbook_path = playbook_path
        self.config = config

    def execute(self):
        verbosity = "-vvvvv" if self.config.get('verbose', False) else "-v"
        self._run_ansible_playbook(verbosity, self.playbook_path)

    def _run_ansible_playbook(self, verbosity, playbook_path):
        command = ["ansible-playbook", verbosity, playbook_path]
        logging.debug("Executing Ansible call `%s`", " ".join(command))
        try:
            p = subprocess.Popen(command)
            p.wait()
            if p.returncode != 0:
                # FIXME: parse error codes
                raise RuntimeError("Ansible reported an error when executing playbook %s" % playbook_path)
        except subprocess.CalledProcessError as e:
            logging.error("Error executing Ansible: %s", e)
            raise

