            if key not in result:
                result[key] = default_value

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # get appropriate parser
    parser = getattr(self, parser_name)

    # create a function to convert each argument against the parser's option
    def convert_argument_arg(parser, name, value):
        return parser._get_option_by_name(name).dest, parser._get_option_by_name(name).type(value)

    # for each option in the parser, convert the corresponding value if it exists in values_dict
    for opt in parser._option_list:
        if opt.dest in values_dict and values_dict[opt.dest] is not None:
            values_dict[opt.dest], orig_type = convert_argument_arg(parser, opt.dest, values_dict[opt.dest])
            # check if the converted type is compatible with the option's expected type
            if not isinstance(values_dict[opt.dest], parser._get_option_by_name(opt.dest).type):
                raise ValueError(f"Invalid value type for option {opt.dest}. Got {type(values_dict[opt.dest])} but expected {parser._get_option_by_name(opt.dest).type}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flat_dict = {}
    for root, dirs, files in os.walk(plugin_dir, topdown=True):
        for file in files:
            with open(os.path.join(root, file), 'r') as f:
                lines = f.read().strip().split('\n')
                for line in lines:
                    if '=' in line:
                        key, value = line.split('=', 1)
                        flat_dict[key.replace('_', '-')] = value.replace('"', '')
    return flat_dict

