        for file in files:
            if file == 'plugin_spec.json':
                spec_path = os.path.join(root, file)
                with open(spec_path, 'r') as f:
                    spec = json.load(f)
                    for key, value in spec.items():
                        if value is None or not isinstance(value, dict):
                            continue
                        if key not in specs:
                            specs[key] = {}
                        specs[key].update(value)

    return specs

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    for _, plugin_file in iter(os.walk(plugin_dir)):
        with open(plugin_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    key, value = line.split('=', 1)
                    plugin_spec[key] = value
    return plugin_spec

